import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
import {chromium} from 'playwright-core';
const out=process.env.TRADING_EVIDENCE_DIR;
const browser=await chromium.connectOverCDP(process.env.TRADING_CDP_URL),page=browser.contexts()[0].pages().find(p=>p.url().includes('/trading-proof'));
page.setDefaultTimeout(15000);
const results={views:[],errors:[]};page.on('pageerror',e=>results.errors.push(e.message));
const panel=()=>page.locator('[data-panel-id]:visible').filter({has:page.locator('[data-workspace-section="chart"]')}).first();
const discovery=()=>panel().getByRole('region',{name:'Discover markets',exact:true});
const context=()=>panel().getByRole('region',{name:'Asset participation',exact:true});
const top=()=>page.evaluate(()=>{document.activeElement?.blur();document.querySelectorAll('*').forEach(e=>{if(e.scrollTop)e.scrollTop=0;});});
try{
 await page.setViewportSize({width:1414,height:1000});const cdp=await page.context().newCDPSession(page);await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:false});await page.emulateMedia({reducedMotion:'reduce'});await page.reload();await page.waitForFunction(()=>typeof document.getElementById('trading-open')?.onclick==='function');if(!await page.locator('[data-workspace-host]').count())await page.locator('#trading-open').click();await page.waitForFunction(()=>!!window.tradingFixture);
 await discovery().getByRole('button',{name:'New coins',exact:true}).click();await discovery().getByRole('button',{name:'Open KSTL coin',exact:true}).click();await page.evaluate(()=>{const s=window.tradingFixture.store;window.tradingFixture.state(s.getSnapshot().focused_panel_id,'ready');s.setLayout({order:['chart','activity','trade','details'],hidden:[],split:64});});
 await panel().locator('[data-panel-amount]').fill('123.45');
 await discovery().getByRole('columnheader',{name:'Holders',exact:true}).waitFor();await discovery().getByRole('columnheader',{name:'Posts / theses',exact:true}).waitFor();
 assert.equal(await discovery().getByRole('button',{name:/View MOCHI posts and theses: 0 authored posts, all time/}).innerText(),'0');
 assert.equal(await discovery().getByRole('button',{name:/Inspect full LUMN posts and theses: Authored posts are unavailable/}).innerText(),'—');
 await discovery().getByRole('button',{name:/View KSTL posts and theses:/}).click();await context().getByRole('list',{name:'Coin posts'}).waitFor();assert.equal(await context().getByRole('button',{name:'Posts',exact:true}).getAttribute('aria-pressed'),'true');assert.ok(await context().getByRole('button',{name:'Posts',exact:true}).evaluate(e=>e===document.activeElement));assert.equal(await panel().locator('[data-panel-amount]').inputValue(),'123.45');await page.screenshot({path:out+'/discovery-posts-open.png'});
 await page.evaluate(()=>window.tradingFixture.state(window.tradingFixture.store.getSnapshot().focused_panel_id,'holders-ready'));await discovery().getByRole('button',{name:/View KSTL holders:/}).click();await context().locator('ul li').first().waitFor();assert.equal(await context().getByRole('button',{name:'Holders',exact:true}).getAttribute('aria-pressed'),'true');assert.equal(await panel().locator('[data-panel-amount]').inputValue(),'123.45');await context().getByRole('button',{name:/holder count observation/}).click();await page.keyboard.press('Escape');
 await page.setViewportSize({width:407,height:1000});await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:1});const posts=discovery().getByRole('button',{name:/View KSTL posts and theses:/});await posts.scrollIntoViewIfNeeded();assert.ok((await posts.boundingBox()).height>=44&&(await posts.boundingBox()).width>=44);await posts.click();await context().getByRole('list',{name:'Coin posts'}).waitFor();assert.ok(await context().getByRole('button',{name:'Posts',exact:true}).evaluate(e=>e===document.activeElement&&e.getBoundingClientRect().top>=0&&e.getBoundingClientRect().bottom<=innerHeight));assert.equal(await panel().locator('[data-panel-amount]').inputValue(),'123.45');
 await context().getByRole('button',{name:'Trades',exact:true}).click();await page.evaluate(()=>window.tradingFixture.state(window.tradingFixture.store.getSnapshot().focused_panel_id,'ready'));
 for(const theme of ['light','dark'])for(const width of [320,407,768,1054,1414]){await page.setViewportSize({width,height:1000});await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:width<1024,maxTouchPoints:1});await page.evaluate(t=>document.querySelector('[data-blast-ui]').setAttribute('data-theme',t),theme);await page.waitForTimeout(300);await discovery().scrollIntoViewIfNeeded();const g=await discovery().evaluate(e=>({width:innerWidth,document:document.documentElement.scrollWidth,w:e.clientWidth,scroll:e.scrollWidth,table:e.querySelector('table').getBoundingClientRect().toJSON(),container:e.getBoundingClientRect().toJSON()}));assert.ok(g.document<=g.width&&g.scroll<=g.w+1,JSON.stringify(g));if(width>=1054)assert.ok(g.table.right<=g.container.right+1);results.views.push({theme,...g});await page.screenshot({path:out+`/community-${theme}-${width}.png`});}
 await page.setViewportSize({width:1414,height:1000});await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:false});await page.evaluate(()=>window.discoveryFixture.state='unknown');await discovery().getByRole('button',{name:'Refresh discovery'}).click();await discovery().getByRole('button',{name:/Inspect full KSTL holder count: Holder count is not indexed/}).waitFor();assert.equal(await discovery().getByRole('button',{name:/Inspect full KSTL holder count:/}).innerText(),'—');await page.evaluate(()=>window.discoveryFixture.state='ready');await discovery().getByRole('button',{name:'Refresh discovery'}).click();await discovery().getByRole('button',{name:/View KSTL holders:/}).waitFor();
 for(const theme of ['light','dark']){await page.evaluate(t=>document.querySelector('[data-blast-ui]').setAttribute('data-theme',t),theme);await top();await page.waitForTimeout(300);await page.screenshot({path:out+'/final-'+theme+'.png'});}
 assert.deepEqual(results.errors,[]);writeFileSync(out+'/community-verification.json',JSON.stringify(results,null,2));console.log('PASS community counts, known zero versus unavailable, direct section navigation, focus/scroll, retained draft, touch and 5 widths in both themes');
}finally{await browser.close();}
